/// <summary>
///     The <c>AVATonnageUIBuilder</c> class is the execution class for <c>Tonnage</c>
/// </summary>
class AVATonnageUIBuilder extends SysOperationAutomaticUIBuilder
{
    AVATonnageContract  contract;

    DialogField df_TonnageAutomaticMode;
    DialogField df_TonnagePercentageWarning;
    DialogField df_TonnageDaysForwardCalculation;
    DialogField df_TonnageInventSiteId;
    DialogField df_TonnageStartDate;
    DialogField df_TonnageEndDate;

}

Method.Source:
/// <summary>
///    AVA <c>getContract</c> method.
/// </summary>
/// <returns>
///    <c>AVABPInfoContract</c> as return value
/// </returns>
private AVATonnageContract getContract()
{
    if(!contract)
    {
        contract = this.dataContractObject() as AVATonnageContract;
    }
    return contract;
}

/// <summary>
///    AVA <c>getFromDialog</c> method.
/// </summary>
public void getFromDialog()
{
    super();

    this.getContract().parmAutomaticMode(df_TonnageAutomaticMode.value());
    this.getContract().parmTonnageDaysForwardCalculation(df_TonnageDaysForwardCalculation.value());
    this.getContract().parmTonnagePercentageWarning(df_TonnagePercentageWarning.value());
    this.getContract().parmInventSiteId(df_TonnageInventSiteId.value());
    this.getContract().parmStartDate(df_TonnageStartDate.value());
    this.getContract().parmEndDate(df_TonnageEndDate.value());
}

/// <summary>
///    AVA <c>postBuild</c> method.
/// </summary>
public void postBuild()
{
    super();

    // get references to dialog controls after creation
    df_TonnageAutomaticMode             = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                            methodStr(AVATonnageContract, parmAutomaticMode));
    df_TonnageDaysForwardCalculation    = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                            methodStr(AVATonnageContract, parmTonnageDaysForwardCalculation));
    df_TonnagePercentageWarning         = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                            methodStr(AVATonnageContract, parmTonnagePercentageWarning));
    df_TonnageInventSiteId              = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                            methodStr(AVATonnageContract, parmInventSiteId));
    df_TonnageStartDate                 = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                            methodStr(AVATonnageContract, parmStartDate));
    df_TonnageEndDate                   = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                            methodStr(AVATonnageContract, parmEndDate));


    df_TonnageAutomaticMode.enabled(false);
    df_TonnageDaysForwardCalculation.enabled(false);
    df_TonnagePercentageWarning.enabled(false);
    df_TonnageInventSiteId.enabled(false);
    df_TonnageStartDate.enabled(false);
    df_TonnageEndDate.enabled(false);
    //df_TonnagePercentageWarning.visible(false);
}
